"""Offline, read-only publication from saved qualification operands; no new solves."""
import argparse
import base64
import html
import hashlib
import json
import sys
from collections import Counter
from pathlib import Path

sys.path.insert(0, str(Path(__file__).resolve().parents[2]))

from methane.provenance import LOADED_FILES, LOADED_SOURCE
from methane.qualification_analysis import compact, comparisons, numerical_spreads, sensitivity_differences, recovery_windows
from methane.siting.store import digest

ROOT = Path(__file__).resolve().parent


def write(results_path, destination, *, performance=None):
    original = json.loads((ROOT / 'original-seville.json').read_text())
    results = json.loads(results_path.read_text())
    cases = results['cases']
    compact_cases = [compact(c) for c in cases]
    compare = comparisons(cases)
    repeats = numerical_spreads(cases)
    sensitivities = sensitivity_differences(cases)
    evidence = dict(version='autonomy-qualification-publication/1', programme=results['programme'], numerical_sources=sorted({c['source'] for c in cases}), reporting_source=LOADED_SOURCE['content_hash'], original_study=original[0]['study_id'], cases=compact_cases, comparisons=compare, numerical_spreads=repeats, sensitivities=sensitivities, recovery_windows=[dict(study_id=c["study_id"],case_id=c["case_id"],windows=recovery_windows(c)) for c in cases], full_operands=str(results_path.resolve()), full_operands_sha256=digest(results), performance=performance)
    evidence['publication_inputs_sha256']={name:hashlib.sha256((ROOT/name).read_bytes()).hexdigest() for name in ['writeup.py','interpretation.html','evidence-plan.json','next-steps.md','execution-notes.json','original-seville.json','check-report.cjs','performance.json'] if (ROOT/name).exists()}
    destination.parent.mkdir(parents=True,exist_ok=True)
    summary = destination.with_suffix('.json')
    if destination.exists() or summary.exists():
        raise ValueError('Publish to a new report edition; do not overwrite an original report')
    summary.write_text(json.dumps(evidence,indent=2,ensure_ascii=False))
    font=base64.b64encode(LOADED_FILES['assets/fonts/DepartureMono-Regular.woff2']).decode()
    esc=html.escape
    fmt=lambda x: '—' if x is None else f'{0 if abs(x) < .05 else x:,.1f}'
    original_table=''.join(f"<tr><td>{esc(c['controller'])}</td><td>{fmt(c['summary']['methane_kg'])}</td><td>{fmt(c['summary']['capacity_restored_hour'])}</td><td>{fmt(c['summary']['capacity_confirmed_hour'])}</td><td>{fmt(c['summary']['ending']['battery_kwh'])}</td><td>{fmt(c['summary']['ending']['h2_kg'])}</td></tr>" for c in original)
    outcomes=Counter(c['outcome'] for c in compact_cases)
    checked=Counter(c['checks']['status'] if c['checks'] else 'missing' for c in compact_cases)
    def series(c,label):
        return dict(label=label, study_id=c['study_id'], case_id=c['case_id'], rows=[dict(hour=r['hour'], time=r['time'], methane_kg=r['applied']['methane_kg'], battery_kwh=r['state']['battery_kwh'], h2_kg=r['state']['h2_kg'], co2_kg=r['state']['co2_kg'], temperature_c=r['state']['temperature_c'], actual_capacity_kw=r['truth_capacity_kw'], estimated_capacity_kw=r['diagnosis']['capacity_kw'], requested_kw=r['requested']['electrolyser_kw'], applied_kw=r['applied']['electrolyser_kw'], status=r['diagnosis']['status'], solver=r['solver']['status'], solver_details=r['solver'], pv_kw=r['pv_kw'], forecast=r['forecast_source'], human_hours=r['human_hours'], curtailment_kwh=r['curtailed_kwh']) for r in c['timeline']])
    data=dict(cases=compact_cases,series=[series(c,'Original / '+c['controller']) for c in original]+[series(c,c['group']+' / '+c['label']['pair']+' / '+c['label']['arm']+' / seed '+str(c['label']['seed'])+' / repeat '+str(c['label']['repetition'])) for c in cases])
    encoded=json.dumps(data,ensure_ascii=False).replace('<','\\u003c')
    findings=(ROOT/'interpretation.html').read_text() if (ROOT/'interpretation.html').exists() else '<p>The declared experiments are awaiting interpretation. This draft is not a completed qualification.</p>'
    gaps=(ROOT/'evidence-plan.json').read_text() if (ROOT/'evidence-plan.json').exists() else '{}'
    publications=json.loads((ROOT/'publications.json').read_text()) if (ROOT/'publications.json').exists() else []
    links=''.join('<li><a href="'+esc(x['relative_path'],quote=True)+'">'+esc(x['title'])+'</a></li>' for x in publications)
    links='<ul>'+links+'</ul>' if links else '<p>Individual Sites publications are not included in this edition.</p>'
    repeat_rows=''.join(f"<tr><td>{esc(r['group']+' / '+r['pair']+' / '+r['arm'])}</td><td>{r['completed']}/{r['declared']}</td><td>{fmt(r['spreads']['methane_kg'])}</td><td>{'Yes' if r['exact_physical_trace_identity'] is True else 'No' if r['exact_physical_trace_identity'] is False else 'Incomplete'}</td></tr>" for r in repeats)
    performance_text='<p>Performance qualification is not included in this edition.</p>'
    if performance:
        perf_rows=''.join('<tr><td>'+esc(m['label'])+'</td><td>'+fmt(m['observations']['first_input_ms'])+'</td><td>'+fmt(m['observations']['preview_p95_ms'])+'</td><td>'+fmt(m['observations']['render_p95_ms'])+'</td></tr>' for m in performance.get('measurements',[]))
        performance_text='<p>'+esc(performance.get('scope',''))+'</p><div class="scroll" tabindex="0" role="region" aria-label="Recorded interaction performance"><table><thead><tr><th>Measured condition</th><th>First edit / ms</th><th>Input p95 / ms</th><th>Render p95 / ms</th></tr></thead><tbody>'+perf_rows+'</tbody></table></div><p>'+esc(performance.get('interpretation',''))+'</p><details><summary>Samples, exploratory baseline and measurement limits</summary><pre>'+esc(json.dumps(performance,indent=2))+'</pre></details>'

