    values=dict(PUBLICATIONS=links,FONT=font,COUNT=str(len(cases)),HOURS=f"{sum(c['hours'] for c in cases):,}",CHECKED=f"{sum((c.get('independent_check') or {}).get('checks',0) for c in cases):,}",FINDINGS=findings,ORIGINAL=original_table,REPEATS=repeat_rows,SUMMARY=summary.name,PERFORMANCE=performance_text,PROGRAMME=esc(results['programme']),OPERANDS=esc(str(results_path.resolve())),EVIDENCE=esc(json.dumps(dict(checks=checked,outcomes=outcomes))),DATA=encoded,GAPS=gaps.replace('<','\\u003c'))
